import html
import json
from pathlib import Path

import pandas as pd

ROOT=Path(__file__).resolve().parents[1]
RESULTS=ROOT/"research/strategist_lab/results"
GITHUB="https://github.com/afsar20/AfsarSharifProjects.github.io"
VERSION="20261028"
POLICIES={"equal":"Equal amounts","inverse_vol":"More to lower-risk portfolios","minimum_variance":"Lowest estimated combined risk"}
BOOKS=["Technology","Technology and retail","Defensive industries","Cyclical industries","Consumer industries","Broad equities"]
PROJECTS=[
    ("trading-performance","Execution costs and trading results","Execution analysis","Simulated orders · 2025","strategist/execution-monitor.svg"),
    ("portfolio-risk","Portfolio risk and allocation","Portfolio analysis","Public returns · 2015–2025","strategist/portfolio-performance.svg"),
    ("us-equities","US equity market activity","Market structure","Public trading data · 2025","us_market_overview.svg"),
    ("volatility-surface","SPY option volatility","Options data","Saved market snapshot · September 2026","spy_option_volatility.svg"),
]


def esc(value):return html.escape(str(value))


def table(headers,rows):
    return '<div class="table-scroll"><table class="research-table"><thead><tr>'+''.join(
        f'<th scope="col">{esc(h)}</th>' for h in headers)+'</tr></thead><tbody>'+''.join(
        '<tr>'+''.join(f'<td>{esc(c)}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'


def glossary(items):
    return '<dl class="definitions">'+''.join(f'<div><dt>{esc(term)}</dt><dd>{esc(meaning)}</dd></div>' for term,meaning in items)+'</dl>'


def stats(items):
    return '<div class="study-stats">'+''.join(f'<div class="study-stat"><strong>{esc(value)}</strong><span>{esc(label)}</span></div>' for value,label in items)+'</div>'


def figure(name,caption):
    return f'<figure class="figure"><img loading="lazy" src="../assets/images/{esc(name)}" alt="{esc(caption)}"><figcaption>{caption}</figcaption></figure>'


def note(text):return f'<div class="takeaway"><p>{text}</p></div>'


def detail(title,body):return f'<details class="method-detail"><summary>{title}</summary>{body}</details>'


def links(items):return '<div class="source-links">'+''.join(f'<a href="{url}">{label}</a>' for label,url in items)+'</div>'


def header(home=False):
    prefix="" if home else "../"
    return f'''<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><nav class="nav shell" aria-label="Main navigation">
<a class="brand" href="{prefix}index.html">Afsar Sharif<span>Research</span></a>
<ul class="nav-links"><li><a href="{prefix}index.html#work">Projects</a></li><li><a href="{prefix}index.html#about">About</a></li><li><a href="https://github.com/afsar20">GitHub</a></li></ul>
</nav></header>'''


def footer(home=False):
    prefix="" if home else "../"
    return f'''<footer class="site-footer"><div class="shell footer-inner"><p>Afsar Sharif · Equity market research</p><div><a href="{prefix}index.html">All projects</a><a href="https://github.com/afsar20">GitHub</a><a href="https://www.linkedin.com/in/afsar-sharif-75ba42143/">LinkedIn</a></div></div></footer>'''


def wrap(title,description,content,home=False,data=None):
    prefix="" if home else "../"
    script=''
    if data:
        encoded=json.dumps(data,separators=(',',':'),ensure_ascii=False).replace('</','<\\/')
        script=f'<script id="lab-data" type="application/json">{encoded}</script><script src="{prefix}assets/js/strategist-lab.js?v={VERSION}"></script>'
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="description" content="{esc(description)}"><title>{esc(title)} | Afsar Sharif</title>
<link rel="stylesheet" href="{prefix}assets/css/portfolio.css?v={VERSION}">
<link rel="stylesheet" href="{prefix}assets/css/strategist-lab.css?v={VERSION}"></head>
<body>{header(home)}{content}{footer(home)}{script}</body></html>\n'''


def project(index,intro,scope,sections,data=None):
    slug,title,category,source,_=PROJECTS[index]
    metadata=[("Data",source),("Scope",scope),("Code","Python" if index else "Python and SQL")]
    meta=''.join(f'<div><dt>{label}</dt><dd>{esc(value)}</dd></div>' for label,value in metadata)
    nav=''.join(f'<li><a href="#{key}">{i:02d} &nbsp; {label}</a></li>' for i,(key,label,_,_) in enumerate(sections,1))
    article=''.join(f'<section class="report-section" id="{key}"><p class="section-number">{i:02d} / {label}</p><h2>{heading}</h2>{body}</section>\n' for i,(key,label,heading,body) in enumerate(sections,1))
    next_project=PROJECTS[(index+1)%len(PROJECTS)]
    content=f'''<main id="main"><div class="project-heading"><div class="shell">
<div class="breadcrumbs"><a href="../index.html#work">Projects</a> / Study {index+1:02d}</div>
<p class="kicker">{category}</p><h1>{title}</h1><p class="lead">{intro}</p>
<dl class="study-meta">{meta}</dl></div></div>
<div class="shell report-layout"><aside class="contents" aria-label="On this page"><p>In this study</p><ol>{nav}</ol></aside>
<article class="report">{article}<nav class="next-study" aria-label="Other studies"><a href="../index.html#work">All projects</a><a href="{next_project[0]}.html">Next: {next_project[1]}</a></nav></article></div></main>'''
    return wrap(title,intro,content,data=data)


def home(e,p,u):
    summaries=[
        ("Can a change in trading results be traced to execution costs or to the trading signal? This study follows simulated orders from the initial decision to the final profit or loss.","The checks identified the two deliberately introduced problems separately."),
        ("How should money be divided between six portfolios that share some of the same risks? The study compares three allocation methods using historical industry returns.","The lowest-risk method reduced losses and volatility, but also earned a lower return."),
        ("Where did US share trading take place in 2025? I compare exchanges with trading reported outside exchanges, and examine how their shares changed on busy days.",f"Off-exchange trading averaged {u['off_share']:.1%} of daily dollar value."),
        ("A Python application that collects option data from Interactive Brokers and shows how implied volatility varies with strike price and expiry.","The saved sample has higher implied volatility away from the current SPY price."),
    ]
    rows=''
    for i,((slug,title,category,source,image),(summary,result)) in enumerate(zip(PROJECTS,summaries),1):
        rows+=f'''<article class="project-row"><span class="project-index">{i:02d}</span><div class="project-copy"><p class="project-meta">{category} / {source}</p><h3><a href="projects/{slug}.html">{title}</a></h3><p>{summary}</p><p class="project-result">{result}</p><a class="project-link" href="projects/{slug}.html">Read the study →</a></div><a class="project-preview" href="projects/{slug}.html" aria-label="Open {title}"><img src="assets/images/{image}" alt="Chart from {title}" loading="lazy"></a></article>'''
    content=f'''<main id="main"><section class="home-intro"><div class="shell"><p class="kicker">Market structure / Execution / Portfolio risk</p><h1>Equity market research.</h1><p class="intro-copy">Studies of trading activity, execution costs, portfolio risk and options data. Each project explains the question, the method and what the results mean.</p><div class="text-links"><a href="#work">View the projects</a><a href="{GITHUB}">View the code</a></div></div></section>
<section class="shell" id="work"><div class="section-label"><h2>Selected projects</h2><p>Four studies · Code and data included</p></div>{rows}</section>
<section class="shell about-section" id="about"><div><p class="kicker">About</p><h2>About these projects</h2></div><div><p>I work in equity market structure and execution analytics in London. My interests include where liquidity is available, how trading costs affect results, and how portfolios behave when markets change.</p><p>These are personal research projects. The pages identify whether the data are public, collected through a broker, or simulated. The code and methods are available for review.</p><dl class="profile-details"><div><dt>Focus</dt><dd>Equities and execution</dd></div><div><dt>Tools</dt><dd>Python, SQL, Tableau</dd></div><div><dt>Location</dt><dd>London</dd></div></dl></div></section>
<div class="shell archive"><p>Earlier data projects</p><a href="https://github.com/afsar20/PortfolioProjects/blob/main/Movies%20Correlation%20Project.ipynb">Film revenue analysis</a><a href="https://github.com/afsar20/PortfolioProjects/blob/main/CovidDataExploration.sql">COVID-19 data</a><a href="https://github.com/afsar20/PortfolioProjects/blob/main/NashvilleHousing_cleaning_data.sql">Housing data cleaning</a></div></main>'''
    return wrap("Equity market research","Afsar Sharif’s research on equity trading, execution costs, portfolio risk and options data.",content,home=True)


def execution(e):
    venue=pd.read_csv(RESULTS/"execution/venue_monitor.csv")
    signal=pd.read_csv(RESULTS/"execution/signal_monitor.csv")
    interval={r['venue']:r for r in e['venue_intervals']}
    cost=e['components_usd']['is_usd']/e['decision_notional']*10000
    initial_pnl=e['components_usd']['ideal_pnl_usd'];net=e['components_usd']['net_pnl_usd']
    router_dates=venue.loc[venue.incident,'date'];alpha_dates=signal.loc[signal.incident,'date']
    overview=f'''<p>A trading strategy can lose money because the trades cost more to complete, because its price forecasts become less useful, or both. I built a simulated trading record to check whether these causes could be identified separately.</p>
<p>The simulation contains {e['orders']:,} orders. An order is an instruction to buy or sell; a fill is the part that actually trades. All orders, prices, fills and problems in this study were generated for the experiment.</p>'''+stats([(f"{e['orders']:,}","Orders in the simulation"),(f'{cost:.2f} bps',"Total shortfall against the initial trading decision"),(f"{e['test_sessions']}","Trading days reserved for the final test")])+'''
<p>A <strong>basis point (bp)</strong> is 0.01%. A cost of five basis points is about $500 for every $1 million of intended trading. <strong>Shortfall</strong> is the difference between the result at the original decision price and the actual outcome, including fees and the opportunity missed on unfilled orders.</p>'''+note("<strong>Result.</strong> The checks picked up an execution-cost problem and a later decline in forecast quality as separate events. This shows that the calculations and alerts work in the designed example. It does not establish their accuracy on real trading records.")
    terms=glossary([
        ("Execution", "Completing an instruction to buy or sell in the market."),
        ("Parent order / fill", "The parent is the full trading instruction. It may complete through several smaller fills, or remain partly unfilled."),
        ("Venue", "A place where a trade can be executed. Venues A, B and C here are fictional."),
        ("Trading signal", "A forecast used to decide which trades to make. Signal decay means that forecast becomes less useful."),
        ("Spread", "The difference between the best buying price and the best selling price."),
        ("Participation rate", "The order’s share of market trading volume over its chosen period."),
        ("Latency", "The time taken to process an instruction. The chart measures this delay in milliseconds."),
        ("Profit and loss (P&L)", "The money gained or lost by the trades after they are marked at the final price; net P&L also subtracts fees."),
        ("Cost estimate / residual", "The model estimates the cost expected for an order’s conditions. The residual is actual cost minus that estimate; a positive value means the trade cost more than expected."),
    ])
    data='''<p>The records cover 250 trading days in 2025, with three fictional venues and three strategy groups. The only real market input is a measure of recent market volatility, meaning how much market returns varied. Each day’s input uses earlier days only.</p><p>Some orders are only partly filled. Duplicate messages, an unmatched fill and an invalid price are deliberately included to check that they are handled before results are calculated.</p>'''+terms
    method=f'''<ol><li><strong>Check the records.</strong> Match each fill to its order, remove exact duplicate messages and reject invalid entries. Stop the calculation if the fills exceed the amount ordered.</li><li><strong>Explain the trading cost.</strong> Separate price movement before the order reaches the market, later market movement, the execution price, the missed opportunity on unfilled orders and fees.</li><li><strong>Estimate normal costs.</strong> Fit a model using the first 126 days. It accounts for differences such as spread, recent market movement and order size relative to trading volume. Use the next 63 days to choose the model settings and alert threshold.</li><li><strong>Test on later days.</strong> Apply those fixed settings to the final {e['test_sessions']} days, starting {e['test_start']}. Compare actual costs with the estimate and check forecast quality separately.</li></ol>'''+detail("More detail on the model and accounting",f'''<p>The cost model uses Ridge regression: a linear prediction method that limits the size of its fitted coefficients to reduce overfitting. Overfitting means learning patterns specific to the training sample that fail on new data.</p><p>For each venue, daily average cost errors are compared with the middle value and spread of errors in the 63-day calibration sample. A large positive error triggers an alert. A separate alert checks unusually weak signed price moves relative to the original forecast.</p><p>The accounting check is: <code>profit at the decision price − actual net profit = total shortfall</code>. Every order reconciled to within ${e['reconciliation']['max_cost_error_usd']:.2e}, a numerical rounding difference far below one cent.</p><p>The SQL tables and complete formulas are available in the methods file. The model never sees the labels identifying which dates contain a simulated problem.</p>''')
    findings=f'''<h3>Execution cost and delay rose together</h3><p>Venue B’s cost increase runs from {router_dates.min()} to {router_dates.max()}. During those days, its trades cost more than the model expected and its processing delay rises. The other venues do not show the same break.</p>'''+figure("strategist/execution-monitor.svg","Additional execution cost means actual cost minus the model’s estimate. The dashed line starts the final test period. The second chart shows processing delay.")+f'''<p>Across all {e['test_sessions']} test days, Venue B averaged {interval['Venue B']['residual_mean_bps']:.2f} basis points above the estimate. This average includes the days before and after the problem; it is smaller than the six-basis-point increase deliberately inserted during the incident.</p>
<h3>The forecast problem appeared in a different series</h3><p>Strategy group A starts to miss its original price forecasts from {alpha_dates.min()}. Its forecast errors worsen separately from the earlier execution issue. Checking only the final profit would hide that distinction.</p>'''+figure("strategist/signal-decay.svg","Price movement is measured in the trade’s intended direction: up for buys and down for sells. A negative error means the move was less favourable than the forecast.")+f'''<h3>Unfilled orders have a cost too</h3><p>The simulation’s planned trading opportunity was ${initial_pnl/1e6:.2f} million at the original decision prices. After trading costs, missed opportunities and fees, the net result was a loss of ${abs(net)/1e3:,.0f}, rather than that planned gain. These are simulated amounts, used to demonstrate why the whole order needs to be measured.</p>'''+figure("strategist/cost-bridge.svg","Each bar contributes to the total shortfall. All bars use intended trading value as the denominator, so their basis-point values add together.")+note("<strong>Implication.</strong> Investigate the execution process when cost and processing delay rise together. Review the trading forecast when expected price moves fail to appear. The two problems may require different fixes.")
    sensitivity=pd.read_csv(RESULTS/"execution/sensitivity.csv").groupby('shift_bps')[['tp','fp']].sum()
    checks=table(["Check","Result"],[["Main execution incident", "All 15 affected venue-days flagged; no other venue-days flagged"],["Main forecast incident","All 15 affected strategy-days flagged; no other strategy-days flagged"],["Duplicate messages",f"{e['quality']['exact_retries_removed']:,} removed before accounting"],["Invalid records","One unmatched fill and one invalid price excluded"]])+'''
<p>The main problems were deliberately large. I also repeated the cost experiment with three different random seeds and fewer orders per day. A seed fixes the sequence of random draws, making each simulation repeatable.</p>'''+table(["Cost increase inserted","Affected days identified, across three runs","Alerts outside the affected period"],[[f'{shift:.2f} bps',f'{int(row.tp)} of 45',int(row.fp)] for shift,row in sensitivity.iterrows()])+'''
<p>The monitor found all one-basis-point increases, but only 10 of the 45 quarter-basis-point cases. Small changes are harder to distinguish from ordinary variation. In the zero-increase control, it raised no alerts.</p>'''+detail("How the uncertainty range was calculated",'''<p>I repeatedly sampled five-day sections of the final test period and recalculated each venue’s average cost error. Keeping adjacent days together preserves some of the dependence between trading days. This is called a block bootstrap.</p><p>The central 95% of these resampled averages gives an uncertainty range. It describes how sensitive this sample average is to the days included; it is not a guarantee about future costs.</p>'''+table(["Venue","Average extra cost","95% resampling range"],[[r['venue'],f"{r['residual_mean_bps']:.2f} bps",f"{r['ci_low']:.2f} to {r['ci_high']:.2f} bps"] for r in e['venue_intervals']]))
    limits='''<p>The simulation uses a simple cost model and deliberately inserted problems. Real trading includes changing order flow, market conditions, routing decisions and missing information. Similar-looking alerts could have different causes.</p><p>The comparison between venues is descriptive. It cannot show that sending the same real order to another venue would have improved its execution. That would require a fair comparison of comparable orders, or a controlled routing experiment.</p><p>A practical next step would use real orders, quotes and timestamps, then test how often alerts lead to a useful investigation. The current website shows a saved experiment, not a live trading monitor.</p>'''
    code='''<p>The code, SQL calculations, sample records and complete results are available below. The full simulated record can be recreated from the saved inputs.</p>'''+links([("Python analysis",f"{GITHUB}/blob/main/research/strategist_lab/execution.py"),("SQL calculations",f"{GITHUB}/blob/main/research/strategist_lab/sql/diagnostics.sql"),("Notebook",f"{GITHUB}/blob/main/notebooks/trading_performance_diagnostics.ipynb"),("Methods",f"{GITHUB}/blob/main/research/strategist_lab/METHODOLOGY.md"),("Daily results","../research/strategist_lab/results/execution/daily.csv")])+'''<p class="sources">Market-volatility input: Kenneth French Data Library, daily market returns. The source version and file checks are recorded in the <a href="../data/strategist_lab/manifest.json">data record</a>. All trading records are simulated.</p>'''
    monitor='''<p>Choose a venue and period to inspect the saved results. “Extra execution cost” is the difference between the actual cost and the model’s estimate. Positive values mean higher costs. An alert is a request to investigate, not a diagnosis.</p>
<div class="tool"><div class="tool-controls"><label for="venue-filter">Venue<select id="venue-filter"><option value="All">All venues</option><option>Venue A</option><option>Venue B</option><option>Venue C</option></select></label><label for="period-filter">Period<select id="period-filter"><option value="test" selected>Final test period</option><option value="validation">Model checks</option><option value="train">Model training</option><option value="all">Full year</option></select></label></div>
<div class="study-stats" aria-live="polite"><div class="study-stat"><strong id="exec-residual">—</strong><span>Average extra execution cost</span></div><div class="study-stat"><strong id="exec-latency">—</strong><span>Average daily typical delay</span></div><div class="study-stat"><strong id="exec-alerts">—</strong><span>Venue-days flagged for review</span></div></div><p id="exec-live" class="tool-status" aria-live="polite"></p><svg id="execution-chart" class="lab-line-chart" viewBox="0 0 920 260" role="img" aria-label="Extra execution cost by trading day"></svg><p class="table-note">Cost averages weight each filled parent order equally. Delay averages weight each venue’s daily median by its number of filled orders. A median is the middle observation. Alerts are active only in the final test period.</p><noscript>Enable JavaScript to use the filters. The figures and tables below remain available.</noscript></div>'''
    sections=[('question','Overview','What explains a change in trading results?',overview),('data','Data and terms','What the records contain',data),('method','Method','How I separated the causes',method),('monitor','Explore','Inspect the cost monitor',monitor),('results','Results','What the experiment showed',findings),('validation','Checks','How well did the alerts work?',checks),('limits','Limits','What needs testing on real trades',limits),('code','Code and sources','Review the analysis',code)]
    return project(0,"Can weaker trading results be traced to higher execution costs, or to a less useful trading forecast? This simulated study measures the two separately.","100,000 simulated orders",sections,{'project':'execution','rows':json.loads(venue.round(6).to_json(orient='records')),'train_end':e['train_end'],'validation_end':e['validation_end']})


def portfolio(p):
    perf={r['method']:r for r in p['performance']};a=perf['equal'];b=perf['minimum_variance'];tail=p['coverage']['minimum_variance']['var99']
    overview='''<p>Different portfolios can move together because they own similar exposures, even when their names and trading ideas sound different. I compared three ways of dividing money between six example portfolios.</p><p><strong>Volatility</strong> measures how widely returns vary. <strong>Drawdown</strong> is a fall from an earlier high in portfolio value. These describe different aspects of risk: day-to-day variation and the size of losses along the path.</p>'''+stats([(f"{b['annual_vol']:.2%}","Annual volatility with the lowest-risk allocation"),(f"{b['cagr']:.2%}","Equivalent annual growth with that allocation"),(f"{b['max_drawdown']:.2%}","Largest fall from a previous high")])+f'''<p>Equal allocation produced {a['annual_vol']:.2%} volatility and {a['cagr']:.2%} annualised return. The lowest-risk allocation cut volatility by about {1-b['annual_vol']/a['annual_vol']:.0%}, but its return was also lower. Annualised return is the steady yearly growth rate that would produce the same total growth over the test.</p>'''+note("<strong>Result.</strong> Changing the allocation reduced risk in this sample. It did not deliver the same return with less risk. The choice depends on the amount of risk the investor is willing to take.")
    data='''<p>The inputs are real daily returns for ten broad US industries and five common market factors, taken from the Kenneth French Data Library. A return is the percentage gain or loss over a period. A factor is a shared influence on returns, such as the overall market or a preference for smaller companies.</p><p>I used 2015–2019 as prior history, then evaluated the allocation rules during 2020–2025. The six portfolios are illustrative combinations of industry exposures; they are not actual fund returns or directly tradable products.</p>'''+table(["Example portfolio","Main idea"],[[BOOKS[0],"Technology and telecoms versus manufacturing and energy"],[BOOKS[1],"Technology, retail and durable goods versus staples and utilities"],[BOOKS[2],"Staples, healthcare and utilities versus durable goods and manufacturing"],[BOOKS[3],"Manufacturing, energy and other industries versus utilities and staples"],[BOOKS[4],"Retail and durable goods versus telecoms and other industries"],[BOOKS[5],"Equal long exposure to all ten industries"]])+glossary([
        ("Allocation / weight","The fraction of the available money assigned to each example portfolio."),
        ("Long / short","A long position benefits from a price rise. A short position benefits from a price fall and requires borrowing the asset or equivalent exposure."),
        ("Exposure","The amount of risk linked to a particular investment, industry or market influence."),
        ("Correlation","How closely returns move together. +1 means perfectly together, 0 means no linear relationship, and −1 means perfectly opposite movements."),
        ("Risk contribution","How much one portfolio adds to the combined volatility. A negative contribution means it offsets some risk elsewhere."),
        ("Risk budget","The amount of risk allowed for the combined portfolio or for one part of it."),
        ("Transaction / borrowing costs","The assumed cost of changing positions and holding short exposures. They are estimates here, not observed trading costs."),
    ])
    method='''<p>At the start of each month, I compared these rules using only earlier returns:</p>'''+table(["Allocation rule","How it works"],[["Equal amounts","Start with one sixth of the money in each portfolio."],["More to lower-risk portfolios","Give more money to portfolios with lower individual historical volatility. This is also called inverse-volatility weighting."],["Lowest estimated combined risk","Choose weights that minimise estimated total volatility, accounting for how the portfolios move together. This is minimum-variance allocation."]])+'''<p>All three rules use the same limits: 3%–35% in each portfolio and a monthly one-way turnover limit of 15%. Turnover measures how much money is reassigned; buying and selling the same reassigned amount are counted once in this limit. I assume a trading cost of two basis points per dollar bought or sold, and an annual short-borrow cost of 50 basis points. One basis point is 0.01%.</p><p>Risk estimates use the previous 252 trading days, roughly one year. Between monthly changes, weights move with the portfolio values. No current-day return is used to make that day’s decision.</p>'''+detail("More detail on the estimates",'''<p>The covariance matrix records how the returns vary individually and together. I use Ledoit–Wolf shrinkage, which pulls noisy sample estimates towards a simpler structure to make them more stable.</p><p>Risk contributions use the Euler method: each weighted exposure is assigned part of total volatility, and the parts sum to that total. Negative contributions are retained because they identify offsets.</p><p>A separate linear regression estimates sensitivity to five factors: market return, company size, value, profitability and investment. Value compares cheaper with more expensive shares on accounting measures; profitability compares stronger with weaker operating profits; investment compares companies with more conservative versus more aggressive asset growth.</p><p>The Sharpe ratio in the full results measures excess return relative to volatility. Excess return is return above the cash rate. It is reported for context and was not the optimisation target.</p>''')
    results=figure("strategist/portfolio-performance.svg","Growth of $1 and the fall from each allocation’s earlier high. The returns include the study’s assumed trading and borrowing costs.")+table(["Allocation rule","Annualised return","Annual volatility","Largest fall"],[[POLICIES[k],f"{r['cagr']:.2%}",f"{r['annual_vol']:.2%}",f"{r['max_drawdown']:.2%}"] for k,r in perf.items()])+f'''<p>The lowest-risk method’s largest fall was {abs(b['max_drawdown']):.2%}, compared with {abs(a['max_drawdown']):.2%} for equal amounts. On a starting value of $100, those percentages describe a drop from a high of $100 to about ${100*(1+b['max_drawdown']):.2f} versus ${100*(1+a['max_drawdown']):.2f}; the actual test has changing peaks.</p><p>The annualised returns were {b['cagr']:.2%} and {a['cagr']:.2%}, respectively. Reducing exposure to riskier combinations also reduced gains during favourable periods. These figures describe this sample, rather than a promise about the next one.</p>'''+figure("strategist/risk-contributions.svg","Money allocated to each portfolio and its contribution to combined volatility at the final date. A negative contribution indicates a useful offset to other positions.")+f'''<p>At the final date, the defensive portfolio receives about {p['weights'][2]:.0%} of the capital and has a negative risk contribution. It offsets some movement in the other portfolios. The consumer portfolio receives about {p['weights'][4]:.0%} of capital but contributes more volatility than its capital share alone would suggest.</p>'''+figure("strategist/correlation.svg","Relationships between the six example portfolios over the last 252 trading days. Strong positive values indicate similar movement; negative values indicate offsets.")+f'''<p>About {p['factor_model']['common_share']:.0%} of fitted return variance is explained by the five common factors in the final one-year sample. Variance is volatility squared; this calculation separates common influences from the remaining unexplained movement. It suggests much of the portfolio’s risk can be understood through shared market exposures.</p>'''+note("<strong>Implication.</strong> Allocating equal amounts of money does not allocate equal amounts of risk. Review how positions interact, including useful offsets, before changing the weights.")
    scenario=f'''<p>Change the final allocation, volatility assumptions and exposure size. This is a saved risk estimate as of {p['as_of']}, using a $10 million reference portfolio. It does not rerun the historical returns above.</p><p><strong>Value at Risk (VaR)</strong> is a model’s loss threshold for a stated probability and time period. A 99% one-day VaR aims to be exceeded on about one day in 100 if the model is well specified. It is not a maximum possible loss.</p>
<div class="tool"><div class="tool-controls"><label for="allocation-filter">Allocation rule<select id="allocation-filter"><option value="minimum_variance">Lowest combined risk</option><option value="equal">Equal amounts</option><option value="inverse_vol">More to lower-risk portfolios</option></select></label><label for="vol-multiplier">Individual volatility<output id="vol-value">1.00×</output><input id="vol-multiplier" type="range" min="50" max="250" step="5" value="100"></label><label for="correlation-blend">Move towards +1 correlation<output id="corr-value">0%</output><input id="correlation-blend" type="range" min="0" max="100" step="5" value="0"></label><label for="leverage">Exposure size<output id="leverage-value">1.00×</output><input id="leverage" type="range" min="50" max="200" step="5" value="100"></label></div>
<div class="study-stats" aria-live="polite"><div class="study-stat"><strong id="risk-vol">—</strong><span>Estimated annual volatility</span></div><div class="study-stat"><strong id="risk-var">—</strong><span>Model’s 99% one-day loss threshold</span></div><div class="study-stat"><strong id="risk-budget">—</strong><span>Assigned exposure before offsets</span></div></div><p class="tool-status" id="risk-live" aria-live="polite"></p><div class="table-scroll"><table class="research-table"><thead><tr><th scope="col">Example portfolio</th><th scope="col">Money allocated</th><th scope="col">Contribution to annual volatility</th></tr></thead><tbody id="risk-table-body"></tbody></table></div><noscript>Enable JavaScript to use the scenario controls.</noscript></div>
<p>At 100% on the correlation control, all six portfolios are assumed to move perfectly together. Their individual volatility stays fixed. Increasing exposure size from 1× to 2× doubles the positions relative to the $10 million reference value; under this simple model it doubles estimated risk.</p><p>Volatility contributions are shown in percentage points. They add to total volatility, apart from display rounding. The calculation assumes normally distributed daily returns, the familiar symmetric bell curve, and no expected daily gain. Real losses may be larger or more frequent.</p>'''
    validation=f'''<p>I compared the daily loss forecasts with what happened next. A loss beyond the forecast VaR is called an <strong>exception</strong>. A 99% model should have about 1% exceptions when it describes the risk well.</p>'''+stats([(str(tail['exceptions']),"Losses beyond the historical 99% threshold"),(f"{tail['expected_exceptions']:.1f}","Expected over 1,508 days at a 1% rate"),(f"{tail['exception_rate']:.2%}","Observed exception rate")])+figure("strategist/var-backtest.svg","Daily losses and the previous-history 99% loss threshold for the lowest-risk allocation. Marked points are losses larger than the forecast threshold.")+note("<strong>Implication.</strong> The loss model understated the frequency of large losses. Exceptions also occurred close together. Lower overall volatility did not make the tail-risk model reliable.")+'''<p>I also replayed the final allocation through earlier market falls. These are estimates of what that final exposure would have experienced, not the allocation method’s actual results at the time.</p>'''+table(["Historical period","Estimated return","Change on $10 million"],[[r['name'],f"{r['return']:.2%}",f"−${abs(r['pnl_usd']):,.0f}" if r['pnl_usd']<0 else f"${r['pnl_usd']:,.0f}"] for r in p['historical_stress']])+detail("Statistical checks and alternative history lengths",'''<p>The Kupiec coverage test checks whether exceptions occur at the expected frequency. The Christoffersen independence test checks whether one exception changes the chance of another on the following day. A p-value summarises how unusual the observed pattern would be under the tested model. A small value is evidence against that property; a large value does not prove the model correct.</p>'''+table(["99% risk model","Exceptions","Coverage-test p-value","Independence-test p-value"],[[label,r['exceptions'],f"{r['uc_p']:.3f}",f"{r['independence_p']:.3f}"] for key,label in [('var99','Historical returns'),('normal_var99','Normal-return assumption')] for r in [p['coverage']['minimum_variance'][key]]])+'''<p>The allocation comparison was repeated with 126, 252 and 504 prior trading days. The lowest-risk method’s realised annual volatility stayed close to 3.9% across these choices. The full comparison and resampling interval are in the saved results.</p>''')
    limits='''<p>The six portfolios were selected for an understandable risk exercise. Their returns are built from industry research indices, which cannot be bought directly. The study does not establish an implementable investment strategy or the returns of a real fund.</p><p>The source files were downloaded in 2026 and contain revised historical data. The calculations use earlier rows only at each decision, but do not recreate the exact data that would have been available at that time.</p><p>The cost assumptions omit changing borrowing availability, market impact and the cost of trading at scale. The model also excludes options and other investments whose losses can change nonlinearly with market prices.</p><p>Here, overlap means shared exposures inside the example portfolio. It does not measure whether other funds hold the same securities, which is a separate meaning of market crowding.</p>'''
    code=links([("Python analysis",f"{GITHUB}/blob/main/research/strategist_lab/portfolio.py"),("Notebook",f"{GITHUB}/blob/main/notebooks/portfolio_risk_crowding.ipynb"),("Full methods",f"{GITHUB}/blob/main/research/strategist_lab/METHODOLOGY.md"),("Daily forecasts","../research/strategist_lab/results/portfolio/walk_forward.csv"),("Monthly allocations","../research/strategist_lab/results/portfolio/allocations.csv")])+'''<p class="sources">Data: <a href="https://mba.tuck.dartmouth.edu/pages/faculty/ken.french/data_library.html">Kenneth French Data Library</a>, ten industry portfolios and five research factors. Data remain copyright Eugene F. Fama and Kenneth R. French. The <a href="../data/strategist_lab/manifest.json">data record</a> identifies the saved version. Covariance estimate: <a href="https://scikit-learn.org/stable/modules/generated/sklearn.covariance.LedoitWolf.html">scikit-learn’s Ledoit–Wolf method</a>.</p>'''
    sections=[('question','Overview','How does allocation change portfolio risk?',overview),('data','Data and terms','Six example portfolios',data),('method','Method','Three allocation rules',method),('results','Results','Less risk came with a lower return',results),('scenario','Explore','Change the risk assumptions',scenario),('validation','Checks','Did the loss forecasts hold up?',validation),('limits','Limits','How to interpret the comparison',limits),('code','Code and sources','Review the analysis',code)]
    return project(1,"A comparison of three ways to divide money between six example portfolios. The aim is to understand shared risks, losses and the return trade-off.","Six example portfolios",sections,{'project':'portfolio',**p,'book_names':BOOKS})


def us_equities(u):
    overview='''<p>I examined where US share trading was reported during 2025 and whether the balance changed on the busiest days. <strong>On-exchange</strong> trades take place on an exchange. <strong>Off-exchange</strong> trades occur through other trading arrangements and are reported to a FINRA Trade Reporting Facility, or TRF.</p><p>The main measure is <strong>notional value</strong>: price multiplied by the number of shares traded. It describes the dollar value of activity, rather than the number of shares or trades.</p>'''+stats([(f"{u['off_share']:.2%}","Average daily off-exchange share of dollar value"),(f"{u['top_three_share']:.2%}","Top three exchanges’ share of annual on-exchange value"),(f"{100*u['busy_share_difference']:.2f} pp","Off-exchange share on busy days versus other days")])+'''<p>A percentage point is the difference between two percentages. For example, a change from 45% to 42% is a fall of three percentage points, not a 3% relative fall.</p>'''+note("<strong>Result.</strong> Off-exchange trading accounted for a substantial part of activity. On the busiest days, the balance shifted towards exchanges. A market-wide average therefore misses differences between periods and groups of securities.")
    data=f'''<p>Cboe’s daily file contains dollar value, shares and trade counts for each reporting market centre. The study covers {u['sessions']} trading days in 2025. I check for duplicate venue/day records, unmapped venue names and disagreements between the tape totals and the reported overall total.</p><p>The listing tape groups securities by their listing exchange. It identifies the group being traded, not where every trade in that group occurred.</p>'''+glossary([
        ("Venue / market centre","An exchange or reporting facility identified in the dataset. A reporting facility records trades; it is not necessarily the place where they executed."),
        ("FINRA / TRF","FINRA is the US securities-industry self-regulatory organisation. A Trade Reporting Facility receives reports of eligible off-exchange share trades."),
        ("Tape A","Securities listed on the New York Stock Exchange."),
        ("Tape B","Securities listed on other US exchanges outside the Tape A and Nasdaq groups. Many exchange-traded funds are in this group."),
        ("Tape C","Securities listed on Nasdaq."),
        ("Market share","A venue’s activity divided by the total activity in the chosen market and period. The denominator matters."),
        ("Liquidity","The ability to trade an asset at a reasonable cost and size. Trading volume is related to liquidity, but does not measure all of it."),
    ])
    method='''<ol><li>Separate exchange activity from off-exchange reporting, then calculate each day’s shares using dollar value, share count and trade count.</li><li>Compare exchanges separately within Tape A, B and C, so their different listing groups are visible.</li><li>Identify the busiest 10% of days by total dollar value and compare their off-exchange share and exchange concentration with the remaining days.</li><li>Compare each exchange’s average daily share in January–March with October–December, and review unusual changes against its previous 20 trading days.</li></ol>'''
    measure=u['off_share_by_measure']
    results=f'''<h3>The activity measure changes the market-share figure</h3><p>Off-exchange trading averaged {measure['Total Notional']:.1%} of daily dollar value, {measure['Total Shares']:.1%} of shares and {measure['Total Trade Count']:.1%} of trades. These are different views of the same market, not conflicting results. Share counts give more weight to low-priced shares; trade counts give every reported trade the same weight.</p>'''+figure("us_market_overview.svg","Daily dollar value and off-exchange share during 2025. The smoother line averages the latest 20 trading days.")+'''<h3>Exchange leadership depends on the listing group</h3><p>NYSE leads on Tape A, NYSE Arca on Tape B and Nasdaq on Tape C. A venue’s importance therefore depends on which securities are being traded.</p>'''+figure("us_tape_structure.svg","Each column is a separate listing group. Percentages show exchanges’ shares of annual on-exchange dollar value within that group.")+note("<strong>Implication.</strong> Compare venues against the securities and trading periods that matter for the question. A large overall market share does not establish the best execution for a particular order.")
    busy=f'''<p>The busiest {u['busy_sessions']} days are the top 10% by total dollar value. On these days, off-exchange share was {abs(u['busy_share_difference'])*100:.2f} percentage points lower than on the other {u['other_sessions']} days.</p>'''+figure("us_activity_regimes.svg","A comparison of the busiest days with the rest of the year. Each point is one day; the boxes show the middle half of observations and the line marks the median, or middle daily value.")+f'''<p>Exchange trading also became more concentrated. I measure this with the <strong>Herfindahl–Hirschman Index (HHI)</strong>, the sum of squared percentage market shares. One exchange with all activity would score 10,000; a more even spread across exchanges scores lower. The busiest days scored about {u['hhi_difference']:.0f} points higher.</p><p>This is consistent with trading becoming more focused on exchanges, and on a smaller group of them, when total activity is high. Daily totals cannot establish whether auctions, news or other changes caused the pattern.</p>'''+detail("How stable was the difference under resampling?",f'''<p>I repeatedly sampled trading days from each group and recalculated the difference. This bootstrap resampling produces a range of plausible estimates conditional on the days in the sample.</p><p>The central 95% of resampled differences ran from {100*u['busy_share_ci95'][0]:.2f} to {100*u['busy_share_ci95'][1]:.2f} percentage points. All were below zero, so the direction was stable under this check. It does not prove a cause or establish that the same result will hold in another year. The resampling treats days as independent and does not fully account for runs of similar market conditions.</p>''')
    shifts='''<p>Nasdaq and NYSE Arca gained the most average daily on-exchange share between the first and fourth quarters. NYSE and EDGX lost share. The chart reports changes in percentage points, rather than percentage growth.</p>'''+figure("us_share_shifts.svg","Change in average daily exchange share from the first to the fourth quarter of 2025. The denominator is total on-exchange dollar value.")+'''<p>These shifts help identify where to investigate changes in trading behaviour, venue services or the mix of securities. A gain in reported activity is not, by itself, an improvement in execution quality.</p><p>The code also compares the latest daily share with the preceding 20-day average and usual variation. This highlights an unusual move for review; it does not identify its cause.</p>'''
    limits='''<p>A TRF report does not distinguish a wholesaler, an alternative trading system or another broker arrangement. An alternative trading system is a regulated trading venue operating outside a national securities exchange.</p><p>The daily file does not contain order prices, quotes, execution delays, fill probabilities or transaction costs. It cannot show whether a client would have received a better outcome elsewhere. HHI describes concentration, not execution quality.</p><p>To connect these market-wide patterns to execution, I would need order and fill records linked to quotes, venue and trading time. That would allow a comparison of actual outcomes on busy and ordinary days.</p>'''
    code=links([("Notebook",f"{GITHUB}/blob/main/notebooks/us_equities_liquidity_intelligence.ipynb"),("Python analysis",f"{GITHUB}/blob/main/code/us_equities_liquidity.py"),("Saved daily summary","../research/site_data/us_market_daily.csv"),("Cboe source data","https://www.cboe.com/markets/us/equities/market-statistics/historical-market-volume/")])+'''<p class="sources">Source: Cboe historical US equity market volume, based on consolidated US trade reports. Definitions and reporting context: <a href="https://www.finra.org/investors/insights/where-do-stocks-trade">FINRA, Where Do Stocks Trade?</a> This study uses public market totals.</p>'''
    return project(2,"Where did US share trading take place in 2025, and how did the balance between exchanges and off-exchange trading change on busy days?","US market totals",[('question','Overview','Where trading activity took place',overview),('data','Data and terms','What the daily figures measure',data),('method','Method','How I compared the market',method),('results','Results','Shares by measure and listing group',results),('busy-days','Busy days','Activity shifted towards exchanges',busy),('changes','Share changes','How exchange shares changed',shifts),('limits','Limits','What trading totals cannot tell us',limits),('code','Code and sources','Review the analysis',code)])


def volatility():
    d=pd.read_csv(ROOT/'code/volatility_surface/spy_iv_snapshot_sample.csv');sample=d[d.snapshot_time==d.snapshot_time.max()];spot=float(sample.spot.iloc[0]);front=sample[sample.expiration==sample.expiration.min()];near=front.loc[(front.strike-spot).abs().idxmin()];low=front.loc[front.strike.idxmin()]
    overview='''<p>An option gives its holder the right to buy or sell an asset at an agreed price, called the strike, by its expiry date. SPY is an exchange-traded fund that tracks the S&amp;P 500 US share index. A fund traded on an exchange can be bought and sold much like a share.</p><p><strong>Implied volatility</strong> is the amount of future price variation consistent with an option’s price under a pricing model. It reflects the price of uncertainty in the options market; it does not tell us which direction SPY will move.</p>'''+stats([('4','Expiry dates in the saved sample'),('9','Different strike prices across the sample'),(f'{len(sample)} of 36','Observed points in the latest four-by-nine grid')])+f'''<p>The sample was captured on 4 September 2026. SPY’s latest recorded price was ${spot:,.2f}. This is a saved historical capture, not a live quote.</p>'''+note("<strong>Result.</strong> Implied volatility is lowest near SPY’s recorded price and higher at more distant strikes. The chart makes that shape and the gaps in the collected data visible; it does not establish a trading opportunity.")
    data='''<p>The application connects to Interactive Brokers’ trading software and requests SPY option information. The saved file contains 15 captures over about 28 seconds. Each row records a time, SPY price, expiry, strike, option type and model-implied volatility.</p>'''+glossary([
        ("Underlying / spot","The underlying is the asset on which the option is based. Spot is its current market price; here, that asset is SPY."),
        ("Strike / expiry","The strike is the agreed buying or selling price. Expiry is the date the option ends."),
        ("Call / put","A call gives the right to buy the underlying; a put gives the right to sell it at the strike."),
        ("Volatility surface","A view of implied volatility across different strikes and expiry dates."),
        ("Smile / skew","A smile is higher implied volatility away from central strikes. Skew describes an uneven shape across strikes, often with one side higher."),
        ("Annualised volatility","A volatility measure expressed on a one-year scale so options of different lengths can be compared. A value of 20% does not predict a 20% price increase."),
        ("SMART","Interactive Brokers’ routing destination that can send eligible orders to supported exchanges. The chain labelled SMART is used to identify eligible option contracts; it is not one separate exchange."),
        ("Model value","An estimate produced by a pricing model. The saved values come from Interactive Brokers and are not independently recalculated from bid and ask prices."),
    ])
    method='''<ol><li><strong>Identify the contracts.</strong> Confirm SPY’s contract details, obtain its option list and select four nearby expiries and a limited range of strikes around the recorded SPY price.</li><li><strong>Collect the values.</strong> Request model-implied volatility and match each returned message to its option contract. Responses can arrive at different times.</li><li><strong>Save the observations.</strong> Write the time and contract details with every value. This allows the chart to be recreated without an active broker connection.</li><li><strong>Draw the surface.</strong> Use the latest capture and fill missing display points from neighbouring values. These estimated display points are shown separately from observed points in the coverage chart.</li></ol><p>The data include both puts and calls. The saved values are a mixed option sample, rather than a complete quote for every strike and expiry.</p>'''
    result=f'''<p>For the first expiry, 8 September, implied volatility is about {100*near.iv:.1f}% at strike ${near.strike:,.0f}, close to SPY’s ${spot:,.2f} price. It is {100*low.iv:.1f}% at the lower strike of ${low.strike:,.0f}. The shortest-dated line therefore has a pronounced rise towards lower strikes.</p>'''+figure("spy_option_volatility.svg","Left: the saved implied-volatility surface. Right: directly observed values for the nearest expiry; the dashed line marks SPY’s recorded price. Volatility is expressed as an annual percentage.")+'''<p>This means options at these strikes imply different amounts of price variation under the broker’s pricing model. A single volatility number for all strikes would miss that difference.</p><p>Higher implied volatility is not automatically evidence that an option is overpriced. Strike distance, downside protection demand, model inputs and quote quality all affect the comparison. This project displays the observations rather than deciding which options to buy or sell.</p>'''
    coverage=figure("spy_option_coverage.svg","The latest capture contains 33 observed points. Three strike/expiry combinations are missing. The surface fills those display gaps; the coverage chart does not.")+'''<p>The three gaps are at the highest strike in the first three expiries. The renderer extends the nearest available value along those edges. That makes the surface easier to view, but the extended values are estimates and should not be read as market observations.</p><p>Values in a capture also arrive at slightly different times. The saved file helps identify the collection period, but a timestamp does not guarantee every option value was current at exactly the same instant.</p>'''
    limits='''<p>The sample is small and short dated. It uses Interactive Brokers’ model volatility rather than solving for volatility separately from market buying and selling quotes. The spread between those quotes could materially change the conclusion.</p><p>The current chart groups options by strike. A more complete comparison would adjust strike distance for interest rates, expected dividends and the forward price: the price agreed today for delivery at a later date.</p><p>Before using a fitted surface for pricing, I would remove stale or inconsistent quotes and check that option prices obey basic relationships across strikes and expiries. A stale quote has not been updated recently; a crossed quote has a buying price above the selling price.</p>'''+detail("Possible improvements",'''<p>Bid and ask implied volatilities would show the range of values consistent with the two sides of a quote. Arbitrage checks would flag price relationships that could imply a riskless profit under the model’s assumptions.</p><p>SVI, short for Stochastic Volatility Inspired, is a commonly used parametric curve for implied variance. A fitted curve could smooth noisy observations, but its inputs and no-arbitrage conditions would still need checking. Implied variance is implied volatility squared.</p>''')
    code='''<p>The saved sample and offline renderer can be inspected without a broker account. Live collection requires Interactive Brokers Trader Workstation or IB Gateway, API connections enabled, and the relevant market-data subscriptions. An API is the interface used by the Python program to request data from the broker’s software.</p>'''+links([("Live collection code",f"{GITHUB}/blob/main/code/volatility_surface/live_surface.py"),("Snapshot exporter",f"{GITHUB}/blob/main/code/volatility_surface/snapshot_export.py"),("Saved sample CSV",f"{GITHUB}/blob/main/code/volatility_surface/spy_iv_snapshot_sample.csv"),("Offline renderer",f"{GITHUB}/blob/main/code/volatility_surface/render_snapshot.py")])+'''<p class="sources">Data: a saved SPY option sample collected through Interactive Brokers on 4 September 2026. No broker credentials are stored in the project.</p>'''
    return project(3,"Collecting SPY option data and comparing the price variation implied by different strikes and expiry dates.","33 observed points in the latest capture",[('question','Overview','What the option data show',overview),('data','Data and terms','Reading an option observation',data),('method','Method','From the broker feed to a saved chart',method),('results','Results','Volatility varies across strikes',result),('coverage','Data coverage','Observed points and display estimates',coverage),('limits','Limits','What needs checking before pricing',limits),('code','Code and sources','Run or inspect the project',code)])


def build_site(render_figures=True):
    e=json.loads((RESULTS/'execution/metrics.json').read_text())
    p=json.loads((RESULTS/'portfolio/metrics.json').read_text())
    u=json.loads((ROOT/'research/site_data/us_market_summary.json').read_text())
    if render_figures:
        from research.strategist_lab.reports import figures
        from research.site_figures import build_figures
        figures(e,p);build_figures()
    (ROOT/'index.html').write_text(home(e,p,u))
    for slug,document in [('trading-performance',execution(e)),('portfolio-risk',portfolio(p)),('us-equities',us_equities(u)),('volatility-surface',volatility())]:
        (ROOT/f'projects/{slug}.html').write_text(document)


if __name__=='__main__':build_site()
